}
                                        _extra_certs
                                                [_extra_certs_len -
                                                 1] = this_cert;
                                        this_cert = NULL;
                                } else {
                                        if (chain && _chain_len == 0) {
                                                _chain =
                                                    gnutls_malloc(sizeof
                                                                  (_chain
                                                                   [0]) *
