                                                if (!_chain) {
                                                        gnutls_assert();
                                                        ret =
                                                            GNUTLS_E_MEMORY_ERROR;
                                                        goto done;
                                                }
                                                _chain[_chain_len - 1] =
                                                    this_cert;
                                                this_cert = NULL;
                                        } else {
                                                gnutls_x509_crt_deinit
                                                    (this_cert);
